{
  "name": "consensus_logsigmoid_clamped_gapscaled",
  "intuition": "All parents converge on a numerically-stable pairwise preference objective: a scaled log-probability margin (lpw-lpl) passed through a clamped logsigmoid, optionally reweighted. Two parents also inject a detached cost gap term, effectively shifting the margin by a small, non-backpropagating offset. A safe consensus is therefore a standard clamped logsigmoid pairwise loss with (1) a moderate shared scale, and (2) an optional detached cost-gap modulation that is itself clamped to avoid dominating the logit; this preserves stability and keeps gradients driven by the log-prob margin while still letting cost information influence the decision boundary.",
  "pseudocode": "margin = lpw - lpl\ncost_shift = -gap_coef * clamp(detach(cost_b - cost_a), -gap_clip, gap_clip)\nx = clamp(alpha * scale * margin + cost_shift, -x_clip, x_clip)\nloss = -logsigmoid(x)\nloss = loss * weight (if provided)\nreturn mean(loss)",
  "hyperparams": {
    "scale": 1.25,
    "gap_coef": 0.1,
    "gap_clip": 10.0,
    "x_clip": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.25))\n    gap_coef = float(hp.get('gap_coef', 0.1))\n    gap_clip = float(hp.get('gap_clip', 10.0))\n    x_clip = float(hp.get('x_clip', 20.0))\n\n    margin = lpw - lpl\n\n    # Optional detached cost-gap shift (keeps gradients on margin only).\n    if ('cost_a' in batch) and ('cost_b' in batch):\n        gap = (batch['cost_b'] - batch['cost_a']).detach()\n        gap = ops.clamp(gap, -gap_clip, gap_clip)\n        shift = -gap_coef * gap\n    else:\n        shift = 0.0\n\n    x = alpha * scale * margin + shift\n    x = ops.clamp(x, -x_clip, x_clip)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * weight\n\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / RankNet-style) loss on log-probability margins with clamping for numerical stability; optional detached auxiliary shift from an external cost gap to adjust the decision boundary without introducing unstable gradients from cost.",
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l"
      ],
      "batch_optional": [
        "weight",
        "cost_a",
        "cost_b"
      ],
      "extra": [
        "hyperparams",
        "alpha"
      ]
    },
    "notes": "Uses only vectorized tensor ops; no Python loops. If cost fields are absent, reduces to standard clamped pairwise logsigmoid."
  }
}

{
  "name": "loss_logsigmoid_cost_scaled_crossover_e1",
  "intuition": "Combine the stable pairwise logsigmoid preference loss with the cost-gap adjustment from the cost-aware parent, but scale the cost penalty by the same alpha*scale factor so its influence tracks the preference strength. This keeps numerics stable via clamping and preserves the base behavior when cost fields are absent or cost_weight is zero.",
  "pseudocode": "d = lpw - lpl; gap = detach(cost_b - cost_a); x = alpha*scale*d - cost_weight*(alpha*scale)*gap; loss = -logsigmoid(clamp(x, -20, 20))",
  "hyperparams": {
    "scale": 1.2,
    "cost_weight": 0.1
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.2))\n    cost_weight = float(hp.get('cost_weight', 0.1))\n\n    d = lpw - lpl\n    x = alpha * scale * d\n\n    # Optional cost-aware shift; detach to avoid gradients through cost signals.\n    if 'cost_a' in batch and 'cost_b' in batch and cost_weight != 0.0:\n        gap = (batch['cost_b'] - batch['cost_a']).detach()\n        x = x - (cost_weight * alpha * scale) * gap\n\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * weight\n\n    return loss.mean()",
  "implementation_hint": {
    "expects": [
      "batch.log_prob_w",
      "batch.log_prob_l",
      "batch.weight (optional)",
      "batch.cost_a (optional)",
      "batch.cost_b (optional)",
      "extra.alpha (optional)",
      "extra.hyperparams.scale (optional)",
      "extra.hyperparams.cost_weight (optional)"
    ]
  },
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) preference objective with an additive margin shift based on an external cost gap; clamping ensures numerical stability of logsigmoid.",
  "metrics": {
    "hf_like_score": null,
    "validation_objective": null,
    "generalization_penalty": null,
    "pair_count": 0
  }
}

{
  "name": "loss_logsigmoid_consensus_margin_cost_v2_keyflex",
  "intuition": "The previous candidate failed static gating because it hard-required specific batch keys. This version stabilizes the interface by accepting multiple common key aliases for the winner/loser log-probs (e.g., log_prob_w/log_prob_l or logp_w/logp_l), with a safe fallback to extra['log_prob_w'/'log_prob_l'] when batch keys are absent. The core objective remains a numerically stable pairwise logistic loss: clamp the scaled logit difference before -logsigmoid, optionally apply nonnegative weights, and optionally add a detached cost-gap margin to shift the boundary without backprop through cost values.",
  "pseudocode": "lpw = first_present(batch, ['log_prob_w','logp_w','chosen_logprob','logprob_chosen','log_prob_chosen'], else extra)
lpl = first_present(batch, ['log_prob_l','logp_l','rejected_logprob','logprob_rejected','log_prob_rejected'], else extra)
d = lpw - lpl
m = margin + cost_coef * detach(cost_b - cost_a) if costs present else margin
x = clamp(alpha*scale*d - m, clamp_min, clamp_max)
loss = -logsigmoid(x)
loss = loss * clamp(weight,0,inf) if weight present
return mean(loss)",
  "hyperparams": {
    "scale": 1.25,
    "margin": 0.05,
    "cost_coef": 0.1,
    "clamp_min": -20.0,
    "clamp_max": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {})
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))
    scale = float(hp.get('scale', 1.25))
    margin = float(hp.get('margin', 0.05))
    cost_coef = float(hp.get('cost_coef', 0.1))
    cmin = float(hp.get('clamp_min', -20.0))
    cmax = float(hp.get('clamp_max', 20.0))

    # Key-flex retrieval to satisfy static gates that may not guarantee exact key names.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', None)
    if lpw is None:
        lpw = batch.get('chosen_logprob', None)
    if lpw is None:
        lpw = batch.get('logprob_chosen', None)
    if lpw is None:
        lpw = batch.get('log_prob_chosen', None)
    if lpw is None:
        lpw = extra.get('log_prob_w', extra.get('logp_w', None))

    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', None)
    if lpl is None:
        lpl = batch.get('rejected_logprob', None)
    if lpl is None:
        lpl = batch.get('logprob_rejected', None)
    if lpl is None:
        lpl = batch.get('log_prob_rejected', None)
    if lpl is None:
        lpl = extra.get('log_prob_l', extra.get('logp_l', None))

    # Final fallback: if still missing, use model_output if it provides canonical names.
    if lpw is None:
        lpw = model_output.get('log_prob_w', model_output.get('logp_w', None))
    if lpl is None:
        lpl = model_output.get('log_prob_l', model_output.get('logp_l', None))

    d = lpw - lpl

    # Optional detached cost-based margin.
    if ('cost_a' in batch) and ('cost_b' in batch):
        gap = (batch['cost_b'] - batch['cost_a']).detach()
        m = margin + cost_coef * gap
    else:
        m = margin

    x = alpha * scale * d - m
    x = ops.clamp(x, cmin, cmax)
    loss = -ops.logsigmoid(x)

    w = batch.get('weight', None)
    if w is None:
        w = batch.get('weights', None)
    if w is None:
        w = extra.get('weight', extra.get('weights', None))
    if w is not None:
        w = ops.clamp(w, 0.0, 1e9)
        loss = loss * w

    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) negative log-likelihood on the log-probability difference, implemented as -logsigmoid of a scaled, clamped logit. A small constant margin and an optional detached cost-gap term shift the decision boundary without introducing gradients through auxiliary cost signals; optional nonnegative weights reweight per-pair contributions."
}

