{
  "name": "loss_logsigmoid_cost_margin_stable",
  "intuition": "The static gate requires the loss to explicitly expect at least one objective/cost signal, so this stabilizes the original pairwise -logsigmoid ranking loss by (1) declaring cost inputs in expects, (2) using a detached, normalized cost gap as a small margin shift, and (3) clamping the final logit to keep logsigmoid in its stable region. Normalizing the detached cost gap by its batch mean absolute value prevents exploding margins when raw costs have large scale or units.",
  "pseudocode": "pref = lpw - lpl; gap = detach(cost_b - cost_a); norm = mean(abs(gap)) + eps; x = alpha*scale*pref - cost_coef*(gap/norm); x = clamp(x, -clamp, clamp); loss = -logsigmoid(x); return mean(weight*loss)",
  "hyperparams": {
    "scale": 1.5,
    "cost_coef": 0.1,
    "clamp_abs": 20.0,
    "eps": 1e-06
  },
  "expects": {
    "log_prob_w": {
      "shape": [
        "batch"
      ],
      "dtype": "float"
    },
    "log_prob_l": {
      "shape": [
        "batch"
      ],
      "dtype": "float"
    },
    "cost_a": {
      "shape": [
        "batch"
      ],
      "dtype": "float"
    },
    "cost_b": {
      "shape": [
        "batch"
      ],
      "dtype": "float"
    },
    "weight": {
      "shape": [
        "batch"
      ],
      "dtype": "float",
      "optional": true,
      "nonneg": true
    }
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "abs",
    "mean"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    weight = batch.get('weight', None)\n\n    h = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    alpha = float(extra.get('alpha', h.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0\n    scale = float(h.get('scale', 1.5))\n    cost_coef = float(h.get('cost_coef', 0.1))\n    clamp_abs = float(h.get('clamp_abs', 20.0))\n    eps = float(h.get('eps', 1e-6))\n\n    pref = lpw - lpl\n\n    # Detached, normalized cost gap to keep the margin shift scale-invariant and stable.\n    gap = (cost_b - cost_a).detach()\n    denom = ops.mean(ops.abs(gap)) + eps\n    gap_n = gap / denom\n\n    x = alpha * scale * pref - cost_coef * gap_n\n    x = ops.clamp(x, -clamp_abs, clamp_abs)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * weight\n\n    return loss.mean()",
  "theoretical_basis": "Bradley-Terry / pairwise logistic preference loss with a detached cost-based margin shift; batch-normalization of the cost gap and logit clamping improve numerical stability without changing the core preference gradient direction."
}

