  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = extra.get('alpha', hp.get('alpha', 1.0))\n    scale = hp.get('scale', 1.5073452222319776)\n    margin = hp.get('margin', 0.05)\n\n    x = (lpw - lpl) - margin\n    x = x * (alpha * scale)\n    x = ops.clamp(x, -20.0, 20.0)\n\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * ops.clamp(weight, 0.0, 1e9)\n\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) preference loss with a fixed margin encourages a buffer between preferred and non-preferred items. Clamping the logit before logsigmoid is a standard numerical stabilization to avoid extreme saturation and invalid values; non-negative weights preserve preference semantics under weighted averaging."
}

