{
  "name": "loss_logsigmoid_margin_stable_expects_001",
  "intuition": "The static gate failure indicates the runner expects specific batch keys. I keep the original pairwise logsigmoid-with-margin objective but add a strict expects declaration for `log_prob_w` and `log_prob_l` so the interface is satisfied. I also stabilize numerics by clamping logits and sanitizing optional weights (clamp nonnegative, detach) to avoid negative-weight preference inversions and reduce gradient noise from dynamic weighting.",
  "pseudocode": "require log_prob_w, log_prob_l; d = log_prob_w - log_prob_l; x = clamp(alpha*scale*(d - margin), -20, 20); loss = -logsigmoid(x); if weight: loss *= clamp(weight, 0, inf).detach(); return mean(loss)",
  "hyperparams": {
    "scale": 1.5073452222319776,
    "margin": 0.05,
    "clamp_min": -20.0,
    "clamp_max": 20.0
  },
  "operators_used": [
