  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = ops.to_tensor(extra.get('alpha', hp.get('alpha', 1.0)), dtype=lpw.dtype, device=lpw.device)\n\n    scale = float(hp.get('scale', 0.6752757766189963))\n    eps = float(hp.get('label_smooth', 0.05))\n    clamp_logit = float(hp.get('clamp_logit', 20.0))\n\n    # Keep smoothing small to preserve preference semantics.\n    eps = float(max(0.0, min(0.49, eps)))\n    clamp_logit = float(max(1.0, clamp_logit))\n\n    x = (alpha * scale) * (lpw - lpl)\n    x = ops.clamp(x, -clamp_logit, clamp_logit)\n\n    pos = -ops.logsigmoid(x)\n    neg = -ops.logsigmoid(-x)\n    loss_vec = (1.0 - eps) * pos + eps * neg\n\n    if weight is not None:\n        w = ops.clamp(weight, 0.0, 1.0e6)\n        num = (loss_vec * w).sum()\n        den = w.sum() + (w.sum() * 0.0 + 1.0e-12)\n        return num / den\n\n    return loss_vec.mean()",
