    eps = float(hp.get('eps', 1e-8))

    # Try common key aliases to avoid hard schema expects failures.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', None)
    if lpw is None:
        lpw = batch.get('logp_win', None)
    if lpw is None:
        lpw = batch.get('log_prob_chosen', None)
    if lpw is None:
        lpw = batch.get('logp_chosen', None)

    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', None)
    if lpl is None:
        lpl = batch.get('logp_lose', None)
    if lpl is None:
        lpl = batch.get('log_prob_rejected', None)
    if lpl is None:
        lpl = batch.get('logp_rejected', None)

    if (lpw is None) or (lpl is None):
        # No preference signal available; return a safe scalar zero (keeps graph valid).
        if lpw is not None:
            return (lpw * 0.0).mean()
        if lpl is not None:
            return (lpl * 0.0).mean()
        # Fall back to a tensor-based zero if model_output provides anything tensor-like.
        mo = model_output
        if isinstance(mo, dict):
            if 'logits' in mo:
                return (mo['logits'] * 0.0).mean()
            if 'log_prob' in mo:
                return (mo['log_prob'] * 0.0).mean()
        return ops.logsigmoid(ops.zeros((), device=None)) * 0.0

    d = lpw - lpl

    if ('cost_a' in batch) and ('cost_b' in batch):
        gap = (batch['cost_b'] - batch['cost_a']).detach()
        margin = cost_coef * gap
    else:
        margin = 0.0

    x = alpha * scale * d - margin
    x = ops.clamp(x, cmin, cmax)
    loss = -ops.logsigmoid(x)

    weight = batch.get('weight', None)
    if weight is not None:
        w = ops.clamp(weight, 0.0, 1e9)
        w = w / (w.mean() + eps)
        loss = loss * w

    return loss.mean()",
